// Modes 11–50: copy each robot's game setup (engine, arena, links) from its
// first original mode, then add the tier level's own name, goal and difficulty.
// (Opponents, goals and time come from the linked course and the tier level, not mode 1.)
const ENGINE_KEYS = [
  'cat', 'icon', 'color', 'arenaType', 'genre', 'environmentId', 'environmentName', 'environmentEmoji',
  'physics', 'camera', 'linkedFootballCourse', 'linkedFightCourse', 'linkedRaceCourse',
];
for (const chassisId of EXPANDED_ROBOT_IDS) {
  const extraIds = EXPANDED_CHASSIS_MODE_IDS_BY_ROBOT[chassisId] || [];
  if (!CHASSIS_MODE_MAP[chassisId]) CHASSIS_MODE_MAP[chassisId] = [];
  const first = CHASSIS_GAME_MODE_BY_ID[CHASSIS_MODE_MAP[chassisId][0]] || {};
  const engine = Object.fromEntries(ENGINE_KEYS.filter((k) => first[k] !== undefined).map((k) => [k, first[k]]));
  CHASSIS_MODE_MAP[chassisId].push(...extraIds);
  for (const id of extraIds) CHASSIS_GAME_MODE_BY_ID[id] = { ...engine, ...EXPANDED_CHASSIS_MODES[id] };
}

export const ALL_CHASSIS_GAME_MODES = Object.values(CHASSIS_GAME_MODE_BY_ID);

/** All chassis IDs with dedicated mode sets */
export const CHASSIS_MODE_CHASSIS_IDS = Object.keys(CHASSIS_MODE_MAP);

/**
 * Resolve a chassis mode to a playable course — links fight/football modes to engine courses.
 */
export function resolveChassisModeCourse(mode, allCourses = []) {
  if (!mode) return null;
  mode = applyModeCatalog(mode);
  if (mode.chassisId === 'securitybot') mode = applySecurityBotArenaMeta(mode);
  // Kart racers (Rover, Scout…) keep their race tracks; only non-racing studio
  // robots take their arena name, goal and scene from the Arena Bible.
  const studioChassis = isPrimaryStudioChassis(mode.chassisId) && !isCarChassis(mode.chassisId);
  const attach = (resolved) => {
    const studioNamed = studioChassis ? applyPrimaryStudioMeta(resolved) : resolved;
    // Keep the chosen Arena Bible environment while restoring the expansion's
    // tier name, objective and difficulty after the arena supplies its visuals.
    const named = studioNamed;
    const spec = getGameModeSpec(mode.id);
    return {
      ...named,
      isChassisMode: true,
      chassisId: mode.chassisId,
      modeIndex: mode.modeIndex,
      name: kidSafeText(named.name || mode.name),
      desc: kidSafeText(named.desc || mode.desc),
      tagline: kidSafeText(named.tagline || mode.tagline),
      modeSpec: spec ? {
        ...spec,
        environmentName: named.environmentName || spec.environmentName,
        environmentEmoji: named.environmentEmoji || spec.environmentEmoji,
        gameplayDescription: kidSafeText(named.desc || spec.gameplayDescription || ''),
      } : null,
      difficulty: named.difficulty || mode.difficulty,
      modeType: named.modeType || mode.modeType,
      starRequirements: named.starRequirements || mode.starRequirements,
      programmingConcepts: named.programmingConcepts || mode.programmingConcepts,
      estMinutes: named.estMinutes || mode.estMinutes,
      rewardBadge: named.rewardBadge || mode.rewardBadge,
      tryThis: named.tryThis,
      skillLearned: named.skillLearned,
    };
  };

  if (!studioChassis && mode.linkedFightCourse) {
    const linked = allCourses.find((c) => c.id === mode.linkedFightCourse);
    if (linked) {
      return attach({
        ...linked,
        ...mode,
        id: mode.id,
        name: mode.name,
        desc: mode.desc,
        shortName: mode.shortName,
        tagline: mode.tagline,
        arenaType: 'robot_fight',
        genre: 'combat',
        cat: 'combat',
      });
    }
  }
  if (mode.linkedFootballCourse) {
    const linked = allCourses.find((c) => c.id === mode.linkedFootballCourse);
    if (linked) {
      return attach({
        ...linked,
        ...mode,
        id: mode.id,
        name: mode.name,
        desc: mode.desc,
        shortName: mode.shortName,
        tagline: mode.tagline,
        arenaType: 'robot_football',
        genre: 'football',
        cat: 'football',
      });
    }
  }

  if (mode.arenaType === 'flappy_bird' || mode.environmentId === 'flappy') {
    const linked = allCourses.find((c) => c.id === 'flappy_bird');
    if (linked) {
      return attach({
        ...linked,
        ...mode,
        id: mode.id,
        name: mode.modeIndex === 1 ? linked.name : (mode.name || linked.name),
        desc: mode.modeIndex === 1 ? linked.desc : (mode.desc || linked.desc),
        shortName: mode.modeIndex === 1 ? linked.shortName : (mode.shortName || linked.shortName),
        tagline: mode.modeIndex === 1 ? linked.tagline : (mode.tagline || linked.tagline),
        arenaType: 'flappy_bird',
        genre: 'action',
        cat: mode.cat || 'flappy',
      });
    }
  }

  let resolved = applyChassisArenaEnvironment(mode);
  if (isCarChassis(mode.chassisId) && !studioChassis) {
    resolved = applyCarRacingArena(resolved);
  }

  if (!studioChassis && resolved.linkedRaceCourse && isCarChassis(mode.chassisId)) {
    const linked = allCourses.find((c) => c.id === resolved.linkedRaceCourse);
    if (linked) {
      const racing = resolved.raceTrackLabel || resolved.genre === 'racing';
      return attach({
        ...linked,
        ...resolved,
        id: mode.id,
        ...(racing ? {} : {
          name: mode.name,
          desc: mode.desc,
          shortName: mode.shortName,
          tagline: mode.tagline,
        }),
        genre: 'racing',
        cat: 'racing',
      });
    }
  }

  if (!isCarChassis(mode.chassisId) && resolved.linkedRaceCourse) {
    const { linkedRaceCourse: _drop, ...sansRace } = resolved;
    return attach(sansRace);
  }

  return attach(resolved);
}

/** Get this robot's original missions plus its expanded difficulty tiers. */
export function getCoursesForChassis(chassisId, allCourses = []) {
  const key = resolveChassisKey(chassisId);
  const ids = CHASSIS_MODE_MAP[key] ?? CHASSIS_MODE_MAP.custom;
  return ids
    .map((id) => resolveChassisModeCourse(CHASSIS_GAME_MODE_BY_ID[id], allCourses))
    .filter(Boolean);
}

/** Normalize chassis id — unknown/custom builds use the custom mode set */
export function resolveChassisKey(chassisId) {
  if (!chassisId) return 'custom';
  if (CHASSIS_MODE_MAP[chassisId]) return chassisId;
  const normalized = normalizeRobotBuildConfig({ chassisId }).chassisId;
  if (CHASSIS_MODE_MAP[normalized]) return normalized;
  return 'custom';
}

/** Default (first) mode when chassis is selected */
export function getDefaultChassisCourse(chassisId, allCourses = []) {
  const modes = getCoursesForChassis(chassisId, allCourses);
  if (resolveChassisKey(chassisId) === 'footballbot') {
    return modes.find((m) => m.id === 'football_fifa' || m.linkedFootballCourse === 'football_fifa') || modes[0] || null;
  }
  return modes[0] || null;
}

/** True if course belongs to this chassis's 10-mode set */
export function isCourseForChassis(courseId, chassisId) {
  const key = resolveChassisKey(chassisId);
  const ids = CHASSIS_MODE_MAP[key] ?? CHASSIS_MODE_MAP.custom;
  return ids.includes(courseId);
}

export function getChassisIdForCourse(courseId) {
  const mode = CHASSIS_GAME_MODE_BY_ID[courseId];
  return mode?.chassisId || null;
}
